{"rule_name": "BackdoorDLL_ServiceMain", "rationale": "Selected indicators focus on the custom export names and unique byte patterns while ignoring common Windows APIs that appear in benign binaries", "yara_rule": "rule BackdoorDLL_ServiceMain {
  meta:
    description = "Detects backdoor DLL exporting installA and ServiceMain"
    author = "AutoGen"
    risk = "high"
  strings:
    $export1 = "installA" nocase
    $export2 = "ServiceMain" nocase
    $path = "C\\\\Windows\\\\System32\\\\svchost.exe" nocase
    $unique = { 8F 3A 9C 7D }
  condition:
    uint16(0) == 0x5A4D and all of ($export*) and $path and $unique
}"}

{"rule_name": "BackdoorDLL_C2_Service", "rationale": "Focuses on export names and rare constant patterns; generic API calls are omitted to reduce false positives", "yara_rule": "rule BackdoorDLL_C2_Service {
  meta:
    description = "Detects DLL with ServiceMain used for C2"
    author = "AutoGen"
    risk = "high"
  strings:
    $exp1 = "installA" nocase
    $exp2 = "ServiceMain" nocase
    $path = "C\\\\Windows\\\\System32\\\\svchost.exe" nocase
    $const = { B4 D2 E9 F0 }
  condition:
    uint16(0) == 0x5A4D and $exp1 and $exp2 and $path and $const
}"}

{"rule_name": "BackdoorDLL_Elevate_Service", "rationale": "Highlights the combination of ServiceMain export with privilege‑related constants, ignoring ubiquitous Windows API strings", "yara_rule": "rule BackdoorDLL_Elevate_Service {
  meta:
    description = "Detects elevation backdoor DLL registered via svchost"
    author = "AutoGen"
    risk = "high"
  strings:
    $expA = "installA" nocase
    $expB = "ServiceMain" nocase
    $svc = "C\\\\Windows\\\\System32\\\\svchost.exe" nocase
    $sig = { 5C 3D 2E 1F }
  condition:
    uint16(0) == 0x5A4D and $expA and $expB and $svc and $sig
}"}

{"rule_name": "BackdoorDLL_Pipe_Service", "rationale": "Selects export names and pipe‑related constants; generic API strings are filtered out to avoid noise", "yara_rule": "rule BackdoorDLL_Pipe_Service {
  meta:
    description = "Detects backdoor DLL using ServiceMain and named pipes"
    author = "AutoGen"
    risk = "high"
  strings:
    $e1 = "installA" nocase
    $e2 = "ServiceMain" nocase
    $svchost = "C\\\\Windows\\\\System32\\\\svchost.exe" nocase
    $id = { 9A 8B 7C 6D }
  condition:
    uint16(0) == 0x5A4D and $e1 and $e2 and $svchost and $id
}"}
